server {
    listen 80 default_server;
    listen [::]:80 default_server;
    # HTTPS with a self-signed cert (interim). Do NOT force-redirect 80 -> 443
    # yet: a trusted cert (Let's Encrypt) needs a real domain first. Once a
    # trusted cert is installed, add a redirect here and set COOKIE_SECURE=1
    # in /opt/nxeon/.env.
    listen 443 ssl default_server;
    listen [::]:443 ssl default_server;
    server_name _;

    ssl_certificate     /etc/nxeon/tls/nxeon-selfsigned.crt;
    ssl_certificate_key /etc/nxeon/tls/nxeon-selfsigned.key;
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_prefer_server_ciphers off;

    client_max_body_size 20m;

    location / {
        proxy_pass http://127.0.0.1:3000;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
    }
}

